/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.helpers
 */
async function handler({api, event, helpers}) {
    const item = event.context && event.context.item ? event.context.item.value : {};
    const tableName = 'x_travel_buddy_app_trip_request';

    const payload = {
        u_destination_package: item.title || item.name || 'Gold',
        u_destination: item.destination || item.title || 'Satara',
        u_traveler: api.context.session.user.sys_id,
        u_state: 'pending_approval'
    };

    try {
        const response = await helpers.snHttp(`/api/now/table/${tableName}`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Accept': 'application/json'
            },
            body: JSON.stringify(payload)
        });

        if (helpers.modal) {
            helpers.modal.open('sn_canvas_app_template_toast', {
                alertType: 'success',
                message: 'Trip request created successfully!'
            });
        }
    } catch (error) {
        console.error("Failed to create record:", error);
    }
}
